root = pathlib.Path('src/pages')
def patch(rel, upd):
    p = root / rel
    raw = p.read_text()
    m = re.match(r'^<!--page\s*([\s\S]*?)\s*-->\s*', raw)
    fm = json.loads(m.group(1)); fm.update(upd)
    p.write_text('<!--page\n' + json.dumps(fm, indent=2, ensure_ascii=False) + '\n-->\n' + raw[m.end():])
for rel, (t, d, extra) in M.items():
    patch(rel, {'title': t, 'description': d, **extra})
for slug, (t, d, cat, icon, svc) in B.items():
    patch(f'blog/{slug}.html', {'title': t, 'description': d, 'category': cat, 'icon': icon, 'service': None, 'serviceLink': svc})
print('patched', len(M) + len(B))
